custom_css:
/* 美化名字：脏科幻·像素残响 */
/* 二创作者：mukamuka */
/* 框架编写/整理：墨千尾（discord@这对吗/inkfoxxxx） */
/* 先导篇：字体导入 */
@import url("https://fonts.googleapis.com/css2?family=Great+Vibes&family=Dancing+Script:wght@400;700&display=swap");
@import url("https://fontsapi.zeoseven.com/109/main/result.css"); /* 沐哉像素 */
@import url("https://fontsapi.zeoseven.com/438/main/result.css"); /* 汇文正楷 */
@import url("https://fontsapi.zeoseven.com/480/main/result.css"); /* 仓耳飞白 */

@font-face {
  font-family: "✏️";
  src: url("✏️");
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* ===一、全局控制（脏科幻青橙变量）=== */
:root {
  --cyber-bg: #0c0e0c;
  --cyber-panel: rgba(15, 18, 15, 0.94);
  --cyber-cyan: #3a8f8f;
  --cyber-orange: #b87c4d;
  --cyber-cyan-dim: #2a5e5e;
  --cyber-orange-dim: #7a4e2e;
  --text-light: #c0cfc0;
  --text-dim: #6e7e6e;
  --border-glow: 0 0 6px rgba(58, 143, 143, 0.4);
  --gradient-cyber: linear-gradient(135deg, #3a8f8f 0%, #b87c4d 80%);
  --gradient-dark: linear-gradient(180deg, #0f1410 0%, #050805 100%);
}

body {
  font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
  font-weight: normal;
  font-style: normal;
  color: var(--text-light);
  background-color: var(--cyber-bg);
}

/* === 全局噪点叠加层（脏科幻质感）=== */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 9999;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.08'/%3E%3C/svg%3E");
  opacity: 0.15;
  mix-blend-mode: overlay;
}

.drawer-content,
#table_drawer_content,
.options-content {
  background-color: var(--cyber-panel) !important;
  border: 1px solid var(--cyber-cyan) !important;
  box-shadow: var(--border-glow);
  backdrop-filter: blur(12px);
}

/* ===== 二、顶栏 ===== */
#top-settings-holder {
  background: var(--gradient-dark);
  border-bottom: 2px solid var(--cyber-cyan);
  box-shadow: 0 0 15px rgba(58, 143, 143, 0.3);
}

#top-bar {
  background-color: transparent !important;
}

#top-settings-holder .drawer-icon::before {
  font-size: 20px;
  color: transparent !important;
  background: var(--gradient-cyber);
  -webkit-background-clip: text;
  background-clip: text;
  transition: all 0.2s ease;
  filter: drop-shadow(0 0 5px var(--cyber-cyan));
}

#top-settings-holder .drawer-icon:hover::before {
  filter: drop-shadow(0 0 10px var(--cyber-orange));
  transform: scale(1.1);
}

/* ===== 三、底栏 ===== */
#send_form {
  background: var(--gradient-dark);
  border-top: 2px solid var(--cyber-orange) !important;
  border-radius: 0 !important;
  padding: 10px;
  box-shadow: 0 -2px 15px rgba(184, 124, 77, 0.3);
}

#send_textarea {
  background-color: rgba(0, 20, 25, 0.8) !important;
  border: 1px solid var(--cyber-cyan) !important;
  border-radius: 4px !important;
  color: var(--text-light) !important;
  padding: 8px !important;
  box-shadow: inset 0 0 8px rgba(58, 143, 143, 0.2);
}

#send_form [class*="fa-"]::before {
  font-size: 18px;
  color: transparent !important;
  background: var(--gradient-cyber);
  -webkit-background-clip: text;
  background-clip: text;
  transition: all 0.15s ease;
  filter: drop-shadow(0 0 5px var(--cyber-cyan));
}

#send_form [class*="fa-"]:hover::before {
  filter: drop-shadow(0 0 10px var(--cyber-orange));
  transform: scale(1.15);
}

/* ===== 四、聊天区域 ===== */
#sheld {
  height: calc(var(--doc-height, 100vh) - var(--topBarBlockSize, 45px) - 1px) !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

#chat {
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  overflow-y: scroll !important;
  overflow-x: hidden !important;
  max-height: calc(var(--doc-height, 100vh) - var(--topBarBlockSize, 45px) - 20px) !important;
  padding-left: 6px !important;
  padding-right: 2px !important;
  display: flex;
  flex-direction: column;
  gap: 0px;
}

.mesAvatarWrapper {
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100% !important;
}

.mesAvatarWrapper .avatar {
  position: relative !important;
  margin: 0 0 35px 0 !important;
  width: 100% !important;
  height: 320px !important;
  flex: 0 0 auto !important;
  pointer-events: none !important;
  filter: drop-shadow(0 0 12px var(--cyber-cyan));
}

/* 闪烁红点 + REC 文字（录像指示器） */
.mesAvatarWrapper .avatar::after {
  content: "● REC";
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px 4px 8px;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(2px);
  border: 1px solid rgba(255, 0, 0, 0.5);
  border-radius: 20px;
  font-family: "MuzaiPixel", monospace;
  font-size: 14px;
  font-weight: bold;
  color: #ffffff;
  letter-spacing: 1px;
  text-shadow: 0 0 5px rgba(255, 0, 0, 0.8);
  box-shadow: 0 0 10px rgba(255, 0, 0, 0.3);
  z-index: 10;
  pointer-events: none;
  animation: blink-rec 2.5s ease-in-out infinite;
}

@keyframes blink-rec {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.2; }
}

.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
  object-position: 50% 20%;
  border-radius: 0 !important;
  border: 2px solid var(--cyber-cyan) !important;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  -webkit-mask-image: linear-gradient(
    to bottom,
    black 60%,
    rgba(0, 0, 0, 0.8) 75%,
    rgba(0, 0, 0, 0.4) 88%,
    rgba(0, 0, 0, 0.1) 95%,
    transparent 100%
  );
  mask-image: linear-gradient(
    to bottom,
    black 60%,
    rgba(0, 0, 0, 0.8) 75%,
    rgba(0, 0, 0, 0.4) 88%,
    rgba(0, 0, 0, 0.1) 95%,
    transparent 100%
  );
  pointer-events: auto !important;
  -webkit-user-drag: none !important;
  user-select: none !important;
  -webkit-touch-callout: none !important;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: contents;
  color: var(--text-dim);
}

#chat .ch_name {
  position: static;
  align-items: flex-end;
  padding: calc(var(--mainFontSize) * 0.8) 0;
  padding-top: 25px !important;
  font-size: 0.9em;
  color: var(--text-light);
}

#chat .ch_name::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--gradient-cyber);
  box-shadow: 0 0 6px var(--cyber-cyan);
}

.mes {
  width: 100%;
  flex-direction: column !important;
  align-items: center !important;
  border: none !important;
  margin: 0 0 0px 0 !important;
  padding: 0 !important;
  background-color: transparent !important;
  position: relative !important;
}

/* 角色名：MuzaiPixel 像素字体（无黑色描边） */
.mes .ch_name .name_text {
  position: absolute !important;
  top: 310px !important;
  left: 0 !important;
  right: 0 !important;
  margin: 0 auto !important;
  width: 100% !important;
  text-align: center !important;
  font-family: "MuzaiPixel", "TsangerFeiBai W03", monospace !important;
  font-size: 2.2em !important;
  font-weight: normal !important;
  color: var(--cyber-orange) !important;
  z-index: 99 !important;
  pointer-events: none !important;
  display: block !important;
  opacity: 1 !important;
  visibility: visible !important;
  text-shadow:
    0 0 8px var(--cyber-cyan),
    0 0 15px var(--cyber-orange) !important;
  letter-spacing: 2px;
}

.mes_text {
  padding: calc(var(--mainFontSize) * 0.8) 0 0 0;
}

.mes_text q,
.mes_text “q” {
  color: #a0f0f0;                      /* 更亮的青白色 */
  font-style: italic;
  text-shadow: 
    0 0 6px var(--cyber-cyan),
    0 0 10px rgba(160, 240, 240, 0.5); /* 叠加发光，更突出 */
}

.mes_text i,
.mes_text em {
  color: var(--cyber-orange);
  text-shadow: 0 0 4px var(--cyber-orange);
}

.mes_block {
  width: 98%;
  padding-left: 0;
  padding-bottom: 15px;
}

.last_mes .mes_text {
  padding-right: 0;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

div[is_user="false"].last_mes .mes_block {
  padding-bottom: 50px;
}

/* === 用户气泡：脏科幻橙锈 + 水平横纹 + 顶部粗边 === */
div[is_user="true"].mes {
  position: relative !important;
  background: 
    repeating-linear-gradient(
      to bottom,
      rgba(184, 124, 77, 0.15) 0px,
      rgba(184, 124, 77, 0.15) 2px,
      transparent 2px,
      transparent 4px
    ),
    linear-gradient(145deg, rgba(184, 124, 77, 0.55) 0%, rgba(10, 15, 10, 0.95) 100%) !important;
  backdrop-filter: blur(4px);
  border: 2px solid var(--cyber-orange) !important;
  border-radius: 12px;
  margin-bottom: 20px !important;
  box-shadow: 
    0 0 0 1px rgba(58, 143, 143, 0.3),
    0 0 15px rgba(184, 124, 77, 0.4),
    inset 0 0 8px rgba(58, 143, 143, 0.15) !important;
  image-rendering: pixelated;
  overflow: visible !important;
}

div[is_user="true"].mes::before {
  content: "";
  position: absolute;
  top: -2px;
  left: -2px;
  right: -2px;
  height: 6px;
  background: var(--gradient-cyber);
  border-radius: 12px 12px 0 0;
  z-index: 5;
  pointer-events: none;
  box-shadow: 0 0 6px var(--cyber-cyan);
}

div[is_user="true"] .avatar img {
  box-shadow: none !important;
  border: 2px solid var(--cyber-cyan) !important;
}

/* === 机器人气泡：脏科幻青灰 + 水平横纹 + 顶部粗边 === */
div[is_user="false"].mes {
  position: relative !important;
  background: 
    repeating-linear-gradient(
      to bottom,
      rgba(58, 143, 143, 0.12) 0px,
      rgba(58, 143, 143, 0.12) 2px,
      transparent 2px,
      transparent 4px
    ),
    linear-gradient(145deg, rgba(58, 143, 143, 0.6) 0%, rgba(10, 18, 15, 0.95) 100%) !important;
  backdrop-filter: blur(4px);
  border: 2px solid var(--cyber-cyan) !important;
  border-radius: 12px;
  margin-bottom: 20px !important;
  box-shadow: 
    0 0 0 1px rgba(184, 124, 77, 0.3),
    0 0 15px rgba(58, 143, 143, 0.4),
    inset 0 0 8px rgba(184, 124, 77, 0.15) !important;
  image-rendering: pixelated;
  overflow: visible !important;
}

div[is_user="false"].mes::before {
  content: "";
  position: absolute;
  top: -2px;
  left: -2px;
  right: -2px;
  height: 6px;
  background: var(--gradient-cyber);
  border-radius: 12px 12px 0 0;
  z-index: 5;
  pointer-events: none;
  box-shadow: 0 0 6px var(--cyber-orange);
}

div[is_user="false"] .avatar img {
  box-shadow: none !important;
  border: 2px solid var(--cyber-orange) !important;
}

.last_mes .swipeRightBlock {
  margin: 0 10px 0 0;
}

.swipe_left {
  left: calc(8px + 5px);
}

.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
}

.swipes-counter {
  margin-bottom: 4px;
}

#chat .mes.selected {
  background: rgba(58, 143, 143, 0.2) !important;
  box-shadow: 0 0 20px var(--cyber-cyan) !important;
}

body.documentstyle #chat .ch_name::after {
  width: 0;
}

body.documentstyle #chat .mes .mes_block {
  margin-right: 0;
  padding-bottom: 15px;
}

/* ===== 五、滚动条（圆角 + 外发光）===== */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
  background-color: transparent;
}
::-webkit-scrollbar-track {
  background: #0a0f12;
  border-left: 1px solid var(--cyber-cyan);
  border-radius: 10px;
}
::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
  background: var(--gradient-cyber);
  border-radius: 10px;
  box-shadow: 
    0 0 8px var(--cyber-cyan),
    0 0 15px rgba(184, 124, 77, 0.5),
    inset 0 0 6px rgba(0, 0, 0, 0.8);
  border: 1px solid var(--cyber-orange);
}

/* ===== 六、思维链样式 ===== */
.mes_reasoning_details summary {
  list-style: none;
  cursor: pointer;
  display: flex !important;
  align-items: center;
}

.mes_reasoning_header {
  display: flex !important;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-width: 130px;
  background: rgba(0, 20, 25, 0.8);
  border: 1px solid var(--cyber-cyan);
  box-shadow: 0 0 8px var(--cyber-cyan);
  padding: 6px 16px;
  transition: all 0.2s ease-in-out;
  clip-path: polygon(0 0, 100% 0, 95% 100%, 0 100%);
}

.mes_reasoning_details summary:hover .mes_reasoning_header {
  background: rgba(0, 40, 50, 0.9);
  border-color: var(--cyber-orange);
  box-shadow: 0 0 15px var(--cyber-orange);
}

.mes_reasoning_header_title {
  color: var(--cyber-cyan) !important;
  font-size: 0.95em !important;
  text-shadow: 0 0 5px var(--cyber-cyan);
  white-space: nowrap;
}

.mes_reasoning_arrow {
  font-size: 0 !important;
  flex-shrink: 0;
}
.mes_reasoning_arrow::before {
  content: "▶";
  font-size: 12px;
  color: var(--cyber-orange);
  display: inline-block;
  transition: transform 0.2s ease, color 0.2s;
  filter: drop-shadow(0 0 5px var(--cyber-orange));
}
.mes_reasoning_details[open] .mes_reasoning_arrow::before {
  transform: rotate(90deg);
}

.mes_reasoning {
  margin-top: 8px;
  margin-left: 0;
  margin-right: 0;
  padding: 12px 20px;
  background-color: rgba(0, 15, 20, 0.7);
  border: 1px solid var(--cyber-cyan);
  border-left-width: 6px;
  border-left-color: var(--cyber-orange);
  color: #c0e0e8;
  font-size: 0.9em;
  line-height: 1.5;
  max-height: 250px;
  overflow-y: auto;
  backdrop-filter: blur(8px);
}

.mes_reasoning::-webkit-scrollbar {
  width: 4px;
}
.mes_reasoning::-webkit-scrollbar-thumb {
  background: var(--cyber-cyan);
  border-radius: 10px;
  box-shadow: 0 0 6px var(--cyber-orange);
}
.mes_reasoning::-webkit-scrollbar-track {
  background: transparent;
}

.mes_reasoning_details .mes_reasoning_actions .mes_button {
  color: var(--cyber-orange) !important;
  opacity: 0.8;
  transition: all 0.2s ease;
}
.mes_reasoning_details .mes_reasoning_actions .mes_button:hover {
  color: var(--cyber-cyan) !important;
  opacity: 1;
}

/* ===== 七、收藏栏左右滑动查看角色（手机修复版）===== */
#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden !important;
  display: flex !important;
  flex-wrap: nowrap !important;
  justify-content: flex-start !important;
  gap: 12px !important;
  min-height: 120px !important;
  padding: 10px 0 !important;
  margin: 0 !important;
  scrollbar-width: thin;
  scrollbar-color: var(--cyber-cyan) #0a0f12;
  -webkit-overflow-scrolling: touch;
}

#HotSwapWrapper > div .avatar {
  width: 90px !important;
  height: 90px !important;
  flex: 0 0 auto !important;
  border-radius: 0 !important;
  border: 2px solid var(--cyber-cyan) !important;
  box-shadow: 0 0 10px rgba(58, 143, 143, 0.5) !important;
  overflow: hidden !important;
  transition: 0.2s;
}

#HotSwapWrapper > div .avatar:hover {
  border-color: var(--cyber-orange) !important;
  box-shadow: 0 0 15px rgba(184, 124, 77, 0.7) !important;
}

#HotSwapWrapper > div .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 0 !important;
  display: block !important;
  image-rendering: pixelated;
}

#HotSwapWrapper > div::-webkit-scrollbar {
  height: 6px !important;
  background-color: transparent !important;
}
#HotSwapWrapper > div::-webkit-scrollbar-track {
  background-color: #0a0f12 !important;
  border-radius: 10px !important;
  border: 1px solid var(--cyber-cyan);
}
#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background: var(--gradient-cyber) !important;
  border-radius: 10px !important;
  box-shadow: 0 0 8px var(--cyber-cyan), 0 0 12px var(--cyber-orange) !important;
  border: 1px solid var(--cyber-orange);
}

/* ===== 八、表格与代码块 ===== */
.mes_text {
  position: relative;
  padding-bottom: 20px;
}

.mes_text table {
  display: block;
  width: auto;
  min-width: 100%;
  max-width: max-content;
  margin: 12px 0;
  border-collapse: collapse;
  background: rgba(0, 15, 20, 0.85);
  backdrop-filter: blur(8px);
  border: 2px solid var(--cyber-cyan);
  box-shadow: 0 0 15px rgba(58, 143, 143, 0.3);
  overflow-x: auto;
  overflow-y: visible;
  padding-bottom: 6px;
  image-rendering: pixelated;
}

.mes_text table > thead,
.mes_text table > tbody,
.mes_text table > tr {
  display: table;
  width: 100%;
  table-layout: auto;
}

.mes_text table > thead {
  display: table-header-group;
}

.mes_text table > tbody {
  display: table-row-group;
}

.mes_text table tr {
  display: table-row;
}

.mes_text table thead tr {
  background: linear-gradient(90deg, var(--cyber-cyan) 0%, var(--cyber-orange) 100%);
}

.mes_text table th,
.mes_text table td {
  display: table-cell;
  padding: 12px 16px;
  text-align: left;
  vertical-align: top;
  white-space: nowrap;
  font-size: calc(var(--mainFontSize) * 0.9);
  line-height: 1.4;
  border: 1px solid rgba(58, 143, 143, 0.5);
  color: #d0f0ff;
}

.mes_text table th {
  background: transparent;
  color: #000;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  text-shadow: 0 0 5px #fff;
  border-bottom-width: 2px;
  border-color: var(--cyber-orange);
}

.mes_text table td {
  color: var(--text-light);
}

.mes_text table tbody tr:hover {
  background: rgba(58, 143, 143, 0.2) !important;
  box-shadow: inset 0 0 10px var(--cyber-cyan);
}

.mes_text table tbody tr:nth-child(even) {
  background: rgba(184, 124, 77, 0.08);
}

.mes_text table::-webkit-scrollbar {
  height: 6px;
}
.mes_text table::-webkit-scrollbar-track {
  background: #050a0c;
  border: 1px solid var(--cyber-cyan);
  border-radius: 10px;
  margin: 0 12px;
  box-shadow: inset 0 0 3px rgba(0, 0, 0, 0.5);
}
.mes_text table::-webkit-scrollbar-thumb {
  background: var(--cyber-orange);
  border-radius: 10px;
  box-shadow: 0 0 8px var(--cyber-cyan), inset 0 0 6px black;
  border: 1px solid var(--cyber-cyan);
  min-width: 50px;
  max-width: 70vw;
}
.mes_text table::-webkit-scrollbar-thumb:hover {
  background: var(--gradient-cyber);
  box-shadow: 0 0 10px var(--cyber-cyan), 0 0 15px var(--cyber-orange);
}
